(6323532, 935961, 66641, '<td valign="top">The movie playing on the tv is very old, yes?  Love the contrast of that, and a modern young woman on a laptop.  Nice.</td>', 'The movie playing on the tv is very old, yes?  Love the contrast of that, and a modern young woman on a laptop.  Nice.', '2011-02-21 00:34:39.000000', NULL, 1),
(6323533, 934858, 66641, '<td valign="top">great colours, would have loved the tiles to be blurred and the man to be in focus</td>', 'great colours, would have loved the tiles to be blurred and the man to be in focus', '2011-02-21 00:34:44.000000', NULL, 1),
