(6323537, 935439, 66641, '<td valign="top">interesting</td>', 'interesting', '2011-02-21 00:34:52.000000', NULL, 1),
(6323538, 936094, 66641, '<td valign="top">Love the sign, the bike, the shirt, the lamp post, the wreath...but damn, I WISH that car was out of the shot!  Then just a little zoomed in and I think the shot would have been totally different.  Great though.</td>', 'Love the sign, the bike, the shirt, the lamp post, the wreath...but damn, I WISH that car was out of the shot!  Then just a little zoomed in and I think the shot would have been totally different.  Great though.', '2011-02-21 00:34:54.000000', NULL, 1),
(6323540, 936080, 66641, '<td valign="top">Interesting</td>', 'Interesting', '2011-02-21 00:34:58.000000', NULL, 1),
(6323541, 935590, 66641, '<td valign="top">haha, this made me laugh, nice shot</td>', 'haha, this made me laugh, nice shot', '2011-02-21 00:35:01.000000', NULL, 1),
(6323542, 935851, 66641, '<td valign="top">This is a beautiful photo, I really really love it.  But this doesn''t fit in with the theme for me at all.  I think this would do VERY well in another challenge, but I did score this lower because I felt it wasn''t street photography.  But a very beautiful shot.  Very nice.</td>', 'This is a beautiful photo, I really really love it.  But this doesn''t fit in with the theme for me at all.  I think this would do VERY well in another challenge, but I did score this lower because I felt it wasn''t street photography.  But a very beautiful shot.  Very nice.', '2011-02-21 00:35:04.000000', NULL, 1),
(6323545, 936032, 66641, '<td valign="top">priceless look on this guy''s face</td>', 'priceless look on this guy''s face', '2011-02-21 00:35:24.000000', NULL, 1),
(6323546, 935526, 66641, '<td valign="top">I like it, the backpack is a little distracting though.  I like the snow and the fence.  The guy''s stance is great.</td>', 'I like it, the backpack is a little distracting though.  I like the snow and the fence.  The guy''s stance is great.', '2011-02-21 00:35:26.000000', NULL, 1),
(6323549, 936159, 66641, '<td valign="top">Interesting, I''m curious to see some of the other shots you got from this.  I feel like a different angle might have worked better.</td>', 'Interesting, I''m curious to see some of the other shots you got from this.  I feel like a different angle might have worked better.', '2011-02-21 00:35:30.000000', NULL, 1),
(6323606, 935837, 66641, '<td valign="top">lovely photo, but not so "street" for me</td>', 'lovely photo, but not so "street" for me', '2011-02-21 00:46:01.000000', NULL, 1),
(6323611, 936105, 66641, '<td valign="top">Love the girl staring right into the camera, that was the first thing I noticed.  Nice capture.  <br/> <br/>I do wish it was sharper and not so dark.  The balloons are a nice addition to the photo and I would like them to be more visible, but they''re hidden in the dark, which is unfortunate.  I think maybe trying this from many different angles might have helped, if you didn''t do that already.  <br/> <br/>I can''t tell if I think the reflections in the window are interesting or distracting, hmm...<br/> <br/>Love the little girl in pink looking down, so cute. Again, looks like this was caught at just the right moment. :)</td>', 'Love the girl staring right into the camera, that was the first thing I noticed.  Nice capture.   I do wish it was sharper and not so dark.  The balloons are a nice addition to the photo and I would like them to be more visible, but they''re hidden in the dark, which is unfortunate.  I think maybe trying this from many different angles might have helped, if you didn''t do that already.   I can''t tell if I think the reflections in the window are interesting or distracting, hmm... Love the little girl in pink looking down, so cute. Again, looks like this was caught at just the right moment. :)', '2011-02-21 00:47:07.000000', NULL, 1),
(6324983, 936001, 117474, '<td valign="top">Heh. Love the title. Good work!</td>', 'Heh. Love the title. Good work!', '2011-02-21 13:57:38.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6325244, 935186, 68947, '<td valign="top">I have a different perspective of what true Street Photography is from the truest meaning of the word but, DPC seems to have its own version of it.  This one is on the street, well set up and well posed for but, that is the problem...it''s POSED for.  True SP is not.  (not scoring)</td>', 'I have a different perspective of what true Street Photography is from the truest meaning of the word but, DPC seems to have its own version of it.  This one is on the street, well set up and well posed for but, that is the problem...it''s POSED for.  True SP is not.  (not scoring)', '2011-02-21 16:45:56.000000', NULL, 1),
(6325247, 936084, 68947, '<td valign="top">I have a different perspective of what true Street Photography is from the truest meaning of the word but, DPC seems to have its own version of it.  This one is on the street but, not what is considered true SP outside of DPC.  (not scoring)</td>', 'I have a different perspective of what true Street Photography is from the truest meaning of the word but, DPC seems to have its own version of it.  This one is on the street but, not what is considered true SP outside of DPC.  (not scoring)', '2011-02-21 16:47:15.000000', NULL, 1),
(6325250, 935131, 68947, '<td valign="top">I have a different perspective of what true Street Photography is from the truest meaning of the word but, DPC seems to have its own version of it.  This one is on the street and well photographed but, not really true SP.  (not scoring)</td>', 'I have a different perspective of what true Street Photography is from the truest meaning of the word but, DPC seems to have its own version of it.  This one is on the street and well photographed but, not really true SP.  (not scoring)', '2011-02-21 16:48:04.000000', NULL, 1),
(6325253, 936162, 68947, '<td valign="top">I have a different perspective of what true Street Photography is from the truest meaning of the word but, DPC seems to have its own version of it.  This one is on the street, well taken but, not true SP  (not scoring)</td>', 'I have a different perspective of what true Street Photography is from the truest meaning of the word but, DPC seems to have its own version of it.  This one is on the street, well taken but, not true SP  (not scoring)', '2011-02-21 16:48:38.000000', NULL, 1),
(6325254, 935298, 68947, '<td valign="top">I have a different perspective of what true Street Photography is from the truest meaning of the word but, DPC seems to have its own version of it.  This one is on the street, and fits DPC''s version but, that''s as much as I can say here for it (not scoring)</td>', 'I have a different perspective of what true Street Photography is from the truest meaning of the word but, DPC seems to have its own version of it.  This one is on the street, and fits DPC''s version but, that''s as much as I can say here for it (not scoring)', '2011-02-21 16:49:42.000000', NULL, 1),
(6325255, 935959, 68947, '<td valign="top">Not sure that this is street photography in its truest sense of the word even if this was taken out on the street.  (not scoring)</td>', 'Not sure that this is street photography in its truest sense of the word even if this was taken out on the street.  (not scoring)', '2011-02-21 16:50:40.000000', NULL, 1),
