(6327534, 935853, 23098, '<td valign="top">I like the detail, lights, color, and persons in the scene who are present yet worlds apart...good one for street challenge</td>', 'I like the detail, lights, color, and persons in the scene who are present yet worlds apart...good one for street challenge', '2011-02-22 21:50:58.000000', NULL, 1),
(6327538, 935298, 23098, '<td valign="top">I like the starkness of the image, the men, seeming distressed, looking into the distance. Nice capture.</td>', 'I like the starkness of the image, the men, seeming distressed, looking into the distance. Nice capture.', '2011-02-22 21:54:07.000000', NULL, 1),
(6327539, 935277, 29777, '<td valign="top">not voting, but I love everything about this shot. I can''t stop looking and smiling. The expression is fantastic.</td>', 'not voting, but I love everything about this shot. I can''t stop looking and smiling. The expression is fantastic.', '2011-02-22 21:55:43.000000', NULL, 1),
(6327578, 935051, 96751, '<td valign="top">I guess they know each other...</td>', 'I guess they know each other...', '2011-02-22 22:20:11.000000', NULL, 1),
(6327580, 935410, 96751, '<td valign="top">Love the wall they''re standing against, but would have cropped it at the first landing.</td>', 'Love the wall they''re standing against, but would have cropped it at the first landing.', '2011-02-22 22:20:36.000000', NULL, 1),
(6327584, 936094, 96751, '<td valign="top">Although this has a lot of interesting elements, I feel that they''re all fighting for my attention.  We''re a bit too far from the guys on the bike, who are quite a bit smaller and darker than the car; there''s the sign, and the wreath on the lamppost..</td>', 'Although this has a lot of interesting elements, I feel that they''re all fighting for my attention.  We''re a bit too far from the guys on the bike, who are quite a bit smaller and darker than the car; there''s the sign, and the wreath on the lamppost..', '2011-02-22 22:22:58.000000', NULL, 1),
(6327586, 936047, 96751, '<td valign="top">They''re talking about YOU</td>', 'They''re talking about YOU', '2011-02-22 22:23:30.000000', NULL, 1),
(6327590, 935131, 96751, '<td valign="top">Man, I want to hang out on YOUR streets.  How utterly adorable.  Even the really poor lighting and grainy texture seem to contribute to the image.  Love it.</td>', 'Man, I want to hang out on YOUR streets.  How utterly adorable.  Even the really poor lighting and grainy texture seem to contribute to the image.  Love it.', '2011-02-22 22:24:36.000000', NULL, 1),
(6327592, 936033, 96751, '<td valign="top">Interesting moment.</td>', 'Interesting moment.', '2011-02-22 22:25:19.000000', NULL, 1),
(6327593, 935590, 96751, '<td valign="top">LOL!  Almost didn''t see him.</td>', 'LOL!  Almost didn''t see him.', '2011-02-22 22:25:34.000000', NULL, 1),
(6327597, 936068, 96751, '<td valign="top">Beautiful lighting.  And I love how the stillness of the snow contrast with the blur of living things trying to get out of it.</td>', 'Beautiful lighting.  And I love how the stillness of the snow contrast with the blur of living things trying to get out of it.', '2011-02-22 22:26:49.000000', NULL, 1),
(6327598, 935109, 96751, '<td valign="top">Marvelous moment.  Great use of negative space.</td>', 'Marvelous moment.  Great use of negative space.', '2011-02-22 22:27:20.000000', NULL, 1),
(6327600, 935426, 117113, '<td valign="top">\</td>', '\', '2011-02-22 22:27:57.000000', NULL, 1),
(6327601, 935959, 96751, '<td valign="top">Adorable, although this is more portraiture than street.</td>', 'Adorable, although this is more portraiture than street.', '2011-02-22 22:28:27.000000', NULL, 1),
(6327604, 936041, 96751, '<td valign="top">How literal of you.  Gorgeous tones</td>', 'How literal of you.  Gorgeous tones', '2011-02-22 22:29:27.000000', NULL, 1),
(6327607, 935015, 96751, '<td valign="top">Excellent photojournalism.  Amazing that you were there.</td>', 'Excellent photojournalism.  Amazing that you were there.', '2011-02-22 22:30:50.000000', NULL, 1),
