(6327614, 934643, 96751, '<td valign="top">Nice lines, although a bit dark.</td>', 'Nice lines, although a bit dark.', '2011-02-22 22:32:17.000000', NULL, 1),
(6327617, 935830, 96751, '<td valign="top">Check out those nails!  Great portrait, though not quite street...</td>', 'Check out those nails!  Great portrait, though not quite street...', '2011-02-22 22:32:50.000000', NULL, 1),
(6327619, 936003, 96751, '<td valign="top">Love the private moment and the arcs.</td>', 'Love the private moment and the arcs.', '2011-02-22 22:33:09.000000', NULL, 1),
(6327625, 936104, 96751, '<td valign="top">Don''t think she''s thinking about chicken...  Lovely moment, and that "halo" of bags is gorgeous.  I bet this would be even better in b/w</td>', 'Don''t think she''s thinking about chicken...  Lovely moment, and that "halo" of bags is gorgeous.  I bet this would be even better in b/w', '2011-02-22 22:34:16.000000', NULL, 1),
