(6327853, 934917, 83313, '<td valign="top">Grog impressed by top ten image. Cory-bone is master of magic picture box. May sit at Grog''s table of honor and tell tales of battles won and females photographed.</td>', 'Grog impressed by top ten image. Cory-bone is master of magic picture box. May sit at Grog''s table of honor and tell tales of battles won and females photographed.', '2011-02-23 00:20:25.000000', NULL, 0),
(6327860, 935277, 83313, '<td valign="top">Not your usual! I''m surprised to find this one is yours. It was a 10 for me. Great street photography and an out of the ordinary feel-good element to it.</td>', 'Not your usual! I''m surprised to find this one is yours. It was a 10 for me. Great street photography and an out of the ordinary feel-good element to it.', '2011-02-23 00:22:46.000000', NULL, 0),
