INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6327876, 935109, 66384, '<td valign="top">I love this shot -- the joy, the unusual framing, the high contrast, the shadows. Congratulations on winning a ribbon with such an artistic image.</td>', 'I love this shot -- the joy, the unusual framing, the high contrast, the shadows. Congratulations on winning a ribbon with such an artistic image.', '2011-02-23 00:30:00.000000', NULL, 0),
(6327900, 936001, 54645, '<td valign="top">She really commands the frame, yeah? Wow. The long, prominent shadows mirror the stiletto, but I''m preaching to the choir.</td>', 'She really commands the frame, yeah? Wow. The long, prominent shadows mirror the stiletto, but I''m preaching to the choir.', '2011-02-23 00:41:06.000000', NULL, 0),
(6327904, 934707, 54645, '<td valign="top">I like the energy.</td>', 'I like the energy.', '2011-02-23 00:41:51.000000', NULL, 0),
(6327907, 936062, 54645, '<td valign="top">An add for the iPhone, etc.</td>', 'An add for the iPhone, etc.', '2011-02-23 00:42:45.000000', NULL, 0),
(6327912, 935015, 54645, '<td valign="top">You did well to capture this scene. You can feel the joy and energy.</td>', 'You did well to capture this scene. You can feel the joy and energy.', '2011-02-23 00:44:16.000000', NULL, 0),
